import{_ as i,l,o as e,c as n,v as t,p as s,x as o,d as h,i as d,S as p}from"./chunks/framework.InCnrqk-.js";const D=JSON.parse('{"title":"热板均匀性","description":"","frontmatter":{"title":"热板均匀性","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/hotplate-uniformity.md","filePath":"litho/hotplate-uniformity.md","lastUpdated":1789023840000}'),c={name:"litho/hotplate-uniformity.md"};function _(E,a,m,B,u,f){const r=l("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="热板均匀性" tabindex="-1">热板均匀性 <a class="header-anchor" href="#热板均匀性" aria-label="Permalink to &quot;热板均匀性&quot;">​</a></h1><div class="epigraph"><p>PEB 差一度，酸扩散差一截。热板地图会印到 CD 地图上，看起来像扫描仪场内剂量。</p><footer>—— 对照 PEB 热板多区控温与 CD 相关的工艺实践</footer></div><p><a href="/litho/track-scanner-link">上一课</a>要求尽快 PEB。缺口是：到了热板，温度还是 \\(T(x,y)\\)。主干 <a href="/litho/peb-bake">PEB 温度</a> 写过化学；本课写轨道热板的空间均匀与多区补偿。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>多区加热、边缘散热、接近式气隙、晶圆翘曲，使 PEB 不是一个数。CAR 的 CD 对 PEB 敏感度可以到 nm/°C 量级（依胶而定）。不量热板、只调扫描剂量，会把热地图补偿进光学，换胶或换热板就全塌。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>热板校准用测温晶圆或内嵌传感器，做空间图，调区功率。生产用「PEB 敏感度 × 允许 \\(\\Delta T\\)」进 CDU 预算。接近式气隙必须受控，否则均匀性随片而变。软烤硬烤同样有地图，但 PEB 通常最毒。</p>',7)),(e(),s(p,null,{default:o(()=>[d(r,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20HP%5B%22%E5%A4%9A%E5%8C%BA%E7%83%AD%E6%9D%BF%22%5D%20--%3E%20TXY%5B%22T(x%2Cy)%22%5D%0A%20%20TXY%20--%3E%20DIFF%5B%22%E9%85%B8%E6%89%A9%E6%95%A3%E5%9C%B0%E5%9B%BE%22%5D%0A%20%20DIFF%20--%3E%20CD%5B%22CD%20%E5%9C%B0%E5%9B%BE%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[h(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p><span class="marginnote">边缘场更冷是常见模态。边缘 exclusion 与 EBR 已经切掉一部分，剩下的边缘芯片仍可能吃 PEB 梯度。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>扩散长度 \\(\\propto \\sqrt{D(T)t}\\)，\\(D\\) 对 \\(T\\) 指数敏感。一度的空间差不是线性 CD 差的「一度」，而是 Arrhenius。所以热板规格用温度而不是用「看起来差不多」。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>下一课轨道缺陷：热板颗粒、升华物、背面接触，与温度地图是两条账。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>PEB 热板地图会伪装成光学 CDU。</li><li>多区校准进预算，不要只调剂量。</li><li>出处：PEB 课；热板工艺通识。</li></ul>',7))])}const T=i(c,[["render",_]]);export{D as __pageData,T as default};
